// 客户真实当面声明后才占用交货双方；完成前不预扣价款、不拆库存批次，不预认收入或成本。
#include "task_shop_order_execution.hpp"
#include "resident/model/procurement_timing.hpp"
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
bool same(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
const TaskShopOrderBinding* binding(const TaskShopOrderState& state,const StableId& task){auto found=state.by_task.find(task);return found==state.by_task.end()?nullptr:state.bindings.find(found->second);}
}
Outcome<TaskShopOrderDeliveryQuote> preview_task_shop_order_delivery(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState& state,const PrivateShopOrderRead& shop,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const StableId& actor,const StableId& task_id){
    const auto* task=tasks.tasks.find(task_id);if(!task||task->assignee!=actor)return fail<TaskShopOrderDeliveryQuote>("TaskNotKnown");auto valid=validate_task_shop_order_acceptances(common,tasks,state);if(!valid.ok)return {false,{},valid.error};const auto* b=binding(state,task_id);if(!b||task->status!="active"||!task->settlement_id.empty())return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderDeliveryUnavailable");for(const auto& row:state.actions.rows())if(row.second.task_id==task_id)return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderDeliveryAlreadyActive");
    auto source=shop.private_shop_order_source(b->order_id);if(!source.ok)return {false,{},source.error};if(!source.value||!same(source.value->source_identity,common.state().identity)||source.value->status!="accepted"||source.value->task_id!=task_id||source.value->acceptance_fact_id!=b->fact_id||!task_shop_order_terms_equal(source.value->terms,b->terms))return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderSourceMismatch");const auto& t=b->terms;if(!task_finish_within(common.tick(),task_handover_ticks,t.deadline_tick))return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderDeadlinePassed");
    auto proof=preview_authored_provider_source(common,interaction,catalog,access,actor,t.original_client.id);if(!proof.ok)return {false,{},proof.error};const auto& d=source.value->client_declaration;const auto& m=proof.value.meeting;if(m.actor_id!=actor||proof.value.speaker_actor_id!=t.original_client.id||m.context.provider_actor_id!=d.provider_actor_id||m.context.place_id!=d.place_id||m.context.role_id!=d.role_id||m.dialogue_id!=d.dialogue_id||m.node_id!=d.node_id||m.context.kind||m.context.encounter_id)return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderClientDeclarationRequired");
    const Owner proprietor{Owner::Kind::actor,actor,{}};const auto* inventory=common.inventory(t.stock_inventory_id);const auto* client_inventory=common.inventory(t.client_inventory_id);const auto* income=common.wallet(t.shop_wallet_id);const auto* payer=common.wallet(t.client_wallet_id);if(!inventory||!client_inventory||!income||!payer||!owner_equal(inventory->owner,proprietor)||!owner_equal(income->owner,proprietor)||!owner_equal(client_inventory->owner,t.original_client)||!owner_equal(payer->owner,t.original_client))return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderAssetAuthorityMismatch");
    auto count=common.count(t.stock_inventory_id,t.item_id,{proprietor},{});if(!count.ok)return {false,{},count.error};if(count.value<t.quantity)return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderStockMissing");const ReservationRef key{ReservationRef::Kind::contract,b->reservation_id};Integer amount=-1;for(const auto& r:payer->reserved)if(r.action_id==key){if(amount!=-1)return fail<TaskShopOrderDeliveryQuote>("DuplicateTaskShopOrderReservation");amount=r.amount;}if(amount!=t.contract_price)return fail<TaskShopOrderDeliveryQuote>("TaskShopOrderReservationMismatch");
    return {true,{common.state().identity,task_id,std::move(proof.value),task_handover_ticks},{}};
}
Outcome<StableId> begin_task_shop_order_delivery_in_candidate(CommonStore& common,const TaskState& tasks,TaskShopOrderState& state,const PrivateShopOrderRead& shop,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const TaskShopOrderDeliveryQuote& quote){
    if(!same(common.state().identity,quote.source_identity))return fail<StableId>("StaleTaskShopOrderQuote");auto prepared=preview_task_shop_order_delivery(common,tasks,state,shop,interaction,catalog,access,quote.contact.meeting.actor_id,quote.task_id);if(!prepared.ok)return {false,{},prepared.error};if(prepared.value.duration!=quote.duration)return fail<StableId>("StaleTaskShopOrderQuote");auto valid=revalidate_authored_provider_source(common,interaction,catalog,access,quote.contact);if(!valid.ok)return {false,{},valid.error};
    auto id=common.next_id("action");if(!id.ok)return id;const auto& m=prepared.value.contact.meeting;ActionMutation action;action.kind=ActionMutation::Kind::insert;action.action={id.value,"task_shop_order_deliver",m.actor_id,{m.actor_id,m.context.provider_actor_id},common.tick(),quote.duration};valid=common.apply_action(action);if(!valid.ok)return {false,{},valid.error};for(const auto& participant:action.action.participants){ActorMutation busy;busy.actor_id=participant;busy.action_id=id.value;valid=common.apply_actor(busy);if(!valid.ok)return {false,{},valid.error};}if(!state.actions.insert(id.value,{id.value,quote.task_id,m.context,m.session_id,m.dialogue_id,m.node_id,common.tick()}))return fail<StableId>("DuplicateTaskShopOrderAction");return id;
}
}
